def points(text):
    return np.array([[int(v) for v in pair.split(',')] for pair in text.split()], np.int32)


paths = json.loads((ROOT / 'assets/fnaf4-foxy-masks.json').read_text(encoding='utf-8'))
cuts = json.loads((ROOT / 'tests/fnaf4-background-cuts.json').read_text(encoding='utf-8'))
selected = set(map(int, sys.argv[1:])) if len(sys.argv) > 1 else set(OUTLINES)
for number, parts in OUTLINES.items():
    if number not in selected:
        continue
    rgb = np.asarray(Image.open(ROOT / f"assets/sources/fnaf4/{number}.png").convert("RGB"))
    shape = rgb.shape[:2]
    combined = np.zeros(shape, np.uint8)
    for part in parts:
        polygon = np.zeros(shape, np.uint8)
        cv2.fillPoly(polygon, [points(part)], 255)
        # Refine only the narrow edge band, keeping the entire character interior.
        inner = cv2.erode(polygon, np.ones((9, 9), np.uint8))
        outer = cv2.dilate(polygon, np.ones((9, 9), np.uint8))
        labels = np.where(outer, cv2.GC_PR_BGD, cv2.GC_BGD).astype(np.uint8)
        labels[polygon > 0] = cv2.GC_PR_FGD
        labels[inner > 0] = cv2.GC_FGD
        cv2.setRNGSeed(0)
        cv2.grabCut(rgb, labels, None, np.zeros((1, 65)), np.zeros((1, 65)), 3, cv2.GC_INIT_WITH_MASK)
        refined = np.isin(labels, [cv2.GC_FGD, cv2.GC_PR_FGD]).astype(np.uint8) * 255
        contours, _ = cv2.findContours(refined, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        cv2.drawContours(combined, contours, -1, 255, cv2.FILLED)
    for index, cut in enumerate(cuts[str(number)]):
        if number == 8 and index == 1:
            region = np.zeros(shape, np.uint8)
            cv2.fillPoly(region, [points(cut)], 255)
            red, green, blue = [rgb[:, :, k].astype(float) for k in range(3)]
            combined[(region > 0) & (blue > red * 1.2) & (blue > green * 1.06)] = 0
        else:
            cv2.fillPoly(combined, [points(cut)], 0)
    if number in [7, 18, 19]:
        for wire in parts[2:]:
            cv2.fillPoly(combined, [points(wire)], 255)
    if number == 5:
        combined[0:43, 300:380] = 0
        wire = np.min(rgb[0:43, 300:368], axis=2) > 65
        wire = cv2.dilate(wire.astype(np.uint8), np.ones((3, 3), np.uint8))
        combined[0:43, 300:368][wire > 0] = 255
    if number == 6:
        for x1, y1, x2, y2 in [(329, 31, 346, 46), (359, 22, 374, 47)]:
            wire = np.min(rgb[y1:y2, x1:x2], axis=2) > 65
            wire = cv2.dilate(wire.astype(np.uint8), np.ones((3, 3), np.uint8))
            combined[y1:y2, x1:x2][wire > 0] = 255
    if number in [7, 8]:
        red, green, blue = [rgb[:, :, k].astype(float) for k in range(3)]
        if number == 7:
            toy = (red > 35) & (green > red * .45) & (blue < red * .3)
            combined[200:223, 160:183][toy[200:223, 160:183]] = 0
        else:
            wall = (blue > red * 1.2) & (blue > green * 1.06)
            combined[45:83, 224:267][wall[45:83, 224:267]] = 0
    hooks = {
        1: "169,122 170,133 163,145 155,155 151,163 153,169 159,171 162,176 159,181 153,185 146,186 142,182 140,174 142,165 148,153 158,143 164,131",
        2: "162,237 161,249 154,262 151,271 146,281 145,289 150,294 155,293 158,289 157,296 150,303 144,305 137,301 133,294 132,286 134,274 141,261 149,251 154,238",
        3: "148,351 144,363 130,377 118,388 113,397 118,396 128,395 139,389 145,385 149,390 148,400 133,409 119,410 109,406 106,397 108,386 119,374 133,361 140,349"
    }
    if number in hooks:
        cv2.fillPoly(combined, [points(hooks[number])], 255)
    if number == 4:
        cv2.fillPoly(combined, [points("365,114 371,119 388,107 386,99 380,103")], 255)
    if number in [3, 4]:
        gap = "218,203 250,200 262,200 270,201 274,217 269,227 255,224 241,221 230,228 216,234" if number == 3 else "217,218 231,215 244,211 251,211 260,216 266,217 267,229 264,238 252,238 239,240 228,240 217,245"
        region = np.zeros(shape, np.uint8)
        cv2.fillPoly(region, [points(gap)], 255)
        combined[(region > 0) & (np.min(rgb, axis=2) > 38)] = 0
        if number == 4:
            cv2.fillPoly(combined, [points("176,342 190,329 210,318 229,310 237,309 242,318 248,332 246,345 250,353 253,367 253,386 236,388 217,386 194,373 175,366")], 0)
    if number <= 4:
        red, green, blue = [rgb[:, :, k].astype(float) for k in range(3)]
        exposed_room = np.zeros(shape, np.uint8)
        rectangles = {
            1: [(193, 47, 259, 133), (365, 49, 424, 155)],
            2: [(222, 160, 260, 236), (360, 157, 416, 230)],
            3: [(239, 270, 263, 334)],
            4: [(224, 327, 254, 443)]
        }
        for x1, y1, x2, y2 in rectangles[number]:
            exposed_room[y1:y2, x1:x2] = 255
        room_color = ((blue > red * 1.15) & (blue > green * 1.06) & (blue > 15)) | (np.min(rgb, axis=2) > 55)
        combined[(exposed_room > 0) & room_color] = 0
        toys = np.max(rgb, axis=2) > 15
        toy_regions = np.zeros(shape, np.uint8)
        toy_regions[140:185, 130:170] = 255
        if number == 2: toy_regions[250:292, 130:172] = 255
        if number == 3:
            toy_regions[235:260, 178:210] = 255
            toy_regions[335:375, 125:178] = 255
        combined[(toy_regions > 0) & toys] = 0
    contours, hierarchy = cv2.findContours(combined, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
    segments = []
    for contour in contours:
        if cv2.contourArea(contour) < 8:
            continue
        vertices = cv2.approxPolyDP(contour, .35, True)[:, 0]
        segments.append('M' + 'L'.join(f'{x},{y}' for x, y in vertices) + 'Z')
    paths[number - 1] = ''.join(segments)
    print(f"fnaf4 {number}: {len(contours)} parts", flush=True)
(ROOT / 'assets/fnaf4-foxy-masks.json').write_text(json.dumps(paths), encoding='utf-8')
